var workflow = AgentWorkflowBuilder.BuildSequential(writer, reviewer, editor);

var messages = new List<ChatMessage> { new(ChatRole.User, "Write a tagline for an eBike.") };
await using StreamingRun run = await InProcessExecution.RunStreamingAsync(workflow, messages);
await run.TrySendMessageAsync(new TurnToken(emitEvents: true));
await foreach (WorkflowEvent evt in run.WatchStreamAsync())
    if (evt is AgentResponseUpdateEvent e) Console.Write(e.Update.Text);
